<?php require_once "includes/header.php"; ?>
<?php
$configCompetencias=[
 'hero_kicker'=>'Atribuições e Competências',
 'hero_titulo'=>'Atribuições e Competências',
 'hero_subtitulo'=>'Conheça as principais competências da Assembleia de Freguesia.',
 'intro_titulo'=>'Órgão deliberativo da freguesia',
 'intro_texto'=>'A Assembleia de Freguesia acompanha, aprecia e fiscaliza a atividade da Junta de Freguesia.',
 'destaque_1_titulo'=>'Fiscalização','destaque_1_valor'=>'Acompanhamento da Junta',
 'destaque_2_titulo'=>'Deliberação','destaque_2_valor'=>'Planos, orçamento e contas',
 'destaque_3_titulo'=>'Participação','destaque_3_valor'=>'Debate democrático local'
];
try{$row=$pdo->query("SELECT * FROM assembleia_competencias_config WHERE ativo=1 ORDER BY id ASC LIMIT 1")->fetch(PDO::FETCH_ASSOC);if($row)$configCompetencias=array_merge($configCompetencias,$row);}catch(Exception $e){}
$blocos=[];try{$blocos=$pdo->query("SELECT * FROM assembleia_competencias_blocos WHERE ativo=1 ORDER BY ordem ASC,id ASC")->fetchAll(PDO::FETCH_ASSOC);}catch(Exception $e){}
function compTexto($txt){return nl2br(htmlspecialchars($txt??''));}
function compLista($lista){$linhas=preg_split('/\r\n|\r|\n/',trim($lista??''));$out='';foreach($linhas as $l){$l=trim($l);if($l!=='')$out.='<li>'.htmlspecialchars($l).'</li>';}return $out;}
$fiscalizacao=[];$deliberativa=[];$comunidade=[];$transparencia=[];$outros=[];
foreach($blocos as $b){if($b['tipo']==='fiscalizacao')$fiscalizacao[]=$b;elseif($b['tipo']==='deliberativa')$deliberativa[]=$b;elseif($b['tipo']==='comunidade')$comunidade[]=$b;elseif($b['tipo']==='transparencia'||$b['tipo']==='destaque')$transparencia[]=$b;else $outros[]=$b;}
?>
<style>
.compete-hero{background:radial-gradient(circle at 15% 18%,rgba(212,170,0,.24),transparent 30%),radial-gradient(circle at 90% 12%,rgba(255,255,255,.12),transparent 30%),linear-gradient(135deg,#242A30,#11151B 65%,#071c2e);color:white;padding:92px 0 108px;position:relative;overflow:hidden}.compete-hero:after{content:"";position:absolute;right:-250px;top:-280px;width:620px;height:620px;background:rgba(255,255,255,.07);border-radius:50%}.compete-hero .container{position:relative;z-index:2}.compete-kicker{display:inline-flex;background:rgba(212,170,0,.16);border:1px solid rgba(212,170,0,.38);color:#F0D060;padding:9px 14px;border-radius:999px;font-weight:900;text-transform:uppercase;letter-spacing:.8px;font-size:12px}.compete-hero h1{font-size:clamp(42px,5vw,72px);margin:18px 0 14px;line-height:1.02;max-width:980px}.compete-hero p{max-width:880px;color:#dbeafe;font-size:20px;line-height:1.75;margin:0}.compete-shell{margin-top:-52px;position:relative;z-index:5}.compete-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.compete-stat,.compete-intro,.compete-section{background:white;border:1px solid #e5e7eb;border-radius:30px;padding:28px;box-shadow:0 18px 50px rgba(15,23,42,.08)}.compete-stat span{display:block;color:#64748b;font-weight:900;margin-bottom:8px}.compete-stat strong{display:block;color:#11151B;font-size:25px;line-height:1.2}.compete-intro{display:grid;grid-template-columns:.9fr 1.1fr;gap:26px;align-items:center}.compete-intro h2{margin:0;color:#11151B;font-size:36px;line-height:1.12}.compete-intro p{color:#64748b;line-height:1.8;margin:0;font-size:17px}.compete-section{margin-top:26px}.compete-section h2{color:#11151B;margin:0 0 20px;font-size:34px}.compete-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.compete-card{background:linear-gradient(180deg,#fff,#f8fafc);border:1px solid #e5e7eb;border-radius:26px;padding:24px;transition:.22s ease}.compete-card:hover{transform:translateY(-4px);box-shadow:0 22px 50px rgba(15,23,42,.10)}.compete-card-top{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}.compete-icon{width:66px;height:66px;border-radius:21px;background:linear-gradient(135deg,#242A30,#11151B);color:white;display:grid;place-items:center;font-size:30px;flex-shrink:0}.compete-card h3{margin:0 0 6px;color:#11151B;font-size:24px}.compete-card small{display:block;color:#242A30;font-weight:900}.compete-card p{color:#64748b;line-height:1.75;margin:0 0 14px}.compete-card ul{margin:0;padding-left:20px;color:#334155;line-height:1.8}.compete-highlight{background:linear-gradient(135deg,#242A30,#11151B);color:white;border-radius:30px;padding:30px;margin-top:18px;display:grid;grid-template-columns:80px 1fr;gap:20px;align-items:center;overflow:hidden;position:relative}.compete-highlight:after{content:"";position:absolute;right:-120px;top:-120px;width:260px;height:260px;border-radius:50%;background:rgba(255,255,255,.08)}.compete-highlight>*{position:relative;z-index:2}.compete-highlight .compete-icon{width:80px;height:80px;background:rgba(255,255,255,.14)}.compete-highlight h3{margin:0 0 8px;font-size:28px}.compete-highlight small{color:#F0D060;font-weight:900}.compete-highlight p{color:#dbeafe;line-height:1.75;margin:10px 0 0}.compete-highlight ul{color:#fff;line-height:1.8;margin-top:12px}@media(max-width:1050px){.compete-stats,.compete-intro,.compete-grid{grid-template-columns:1fr}}@media(max-width:720px){.compete-highlight{grid-template-columns:1fr}}
</style>
<section class="compete-hero"><div class="container"><span class="compete-kicker"><?= htmlspecialchars($configCompetencias['hero_kicker']) ?></span><h1><?= htmlspecialchars($configCompetencias['hero_titulo']) ?></h1><p><?= htmlspecialchars($configCompetencias['hero_subtitulo']) ?></p></div></section>
<section class="section compete-shell"><div class="container">
<div class="compete-stats"><div class="compete-stat"><span><?= htmlspecialchars($configCompetencias['destaque_1_titulo']) ?></span><strong><?= htmlspecialchars($configCompetencias['destaque_1_valor']) ?></strong></div><div class="compete-stat"><span><?= htmlspecialchars($configCompetencias['destaque_2_titulo']) ?></span><strong><?= htmlspecialchars($configCompetencias['destaque_2_valor']) ?></strong></div><div class="compete-stat"><span><?= htmlspecialchars($configCompetencias['destaque_3_titulo']) ?></span><strong><?= htmlspecialchars($configCompetencias['destaque_3_valor']) ?></strong></div></div>
<div class="compete-intro"><h2><?= htmlspecialchars($configCompetencias['intro_titulo']) ?></h2><p><?= compTexto($configCompetencias['intro_texto']) ?></p></div>
<?php if(!empty($fiscalizacao)||!empty($deliberativa)): ?><div class="compete-section"><h2>Competências institucionais</h2><div class="compete-grid"><?php foreach(array_merge($fiscalizacao,$deliberativa) as $b): ?><article class="compete-card"><div class="compete-card-top"><div class="compete-icon"><i class="bi <?= htmlspecialchars($b['icone'] ?: 'bi-card-checklist') ?>"></i></div><div><h3><?= htmlspecialchars($b['titulo']) ?></h3><?php if(!empty($b['subtitulo'])): ?><small><?= htmlspecialchars($b['subtitulo']) ?></small><?php endif; ?></div></div><?php if(!empty($b['conteudo'])): ?><p><?= compTexto($b['conteudo']) ?></p><?php endif; ?><?php if(!empty(trim($b['lista']??''))): ?><ul><?= compLista($b['lista']) ?></ul><?php endif; ?></article><?php endforeach; ?></div></div><?php endif; ?>
<?php if(!empty($comunidade)): ?><div class="compete-section"><h2>Comunidade e participação</h2><div class="compete-grid"><?php foreach($comunidade as $b): ?><article class="compete-card"><div class="compete-card-top"><div class="compete-icon"><i class="bi <?= htmlspecialchars($b['icone'] ?: 'bi-people') ?>"></i></div><div><h3><?= htmlspecialchars($b['titulo']) ?></h3><?php if(!empty($b['subtitulo'])): ?><small><?= htmlspecialchars($b['subtitulo']) ?></small><?php endif; ?></div></div><?php if(!empty($b['conteudo'])): ?><p><?= compTexto($b['conteudo']) ?></p><?php endif; ?><?php if(!empty(trim($b['lista']??''))): ?><ul><?= compLista($b['lista']) ?></ul><?php endif; ?></article><?php endforeach; ?></div></div><?php endif; ?>
<?php if(!empty($transparencia)||!empty($outros)): ?><div class="compete-section"><h2>Transparência e responsabilidade</h2><?php foreach(array_merge($transparencia,$outros) as $b): ?><article class="compete-highlight"><div class="compete-icon"><i class="bi <?= htmlspecialchars($b['icone'] ?: 'bi-journal-text') ?>"></i></div><div><h3><?= htmlspecialchars($b['titulo']) ?></h3><?php if(!empty($b['subtitulo'])): ?><small><?= htmlspecialchars($b['subtitulo']) ?></small><?php endif; ?><?php if(!empty($b['conteudo'])): ?><p><?= compTexto($b['conteudo']) ?></p><?php endif; ?><?php if(!empty(trim($b['lista']??''))): ?><ul><?= compLista($b['lista']) ?></ul><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?>
</div></section>
